function parseCSV(text){text=text.replace(/^\uFEFF/,'');const delimiter=text.split(/\r?\n/)[0].includes(';')?';':',';let rows=[],row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if(c==='\n'&&!quoted){row.push(cell.replace(/\r$/,''));if(row.some(v=>v.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('Незакрытые кавычки в CSV.');row.push(cell.replace(/\r$/,''));if(row.some(v=>v.trim()))rows.push(row);const header=rows.shift()?.map(x=>x.trim());const keys=['date','product','sold','prepared','price','cost'];if(!header||keys.some(k=>!header.includes(k)))throw Error('Нужны колонки: '+keys.join(', '));return rows.map(r=>Object.fromEntries(keys.map(k=>[k,r[header.indexOf(k)]])));}
function validate(rows){if(!Array.isArray(rows)||!rows.length||rows.length>20000)throw Error('Нужно от 1 до 20 000 записей.');const seen=new Set(),map=new Map();const out=rows.map((r,i)=>{const product=String(r.product??'').trim(),date=String(r.date??'').trim();if(!product||product.length>100||/^[=+@\-]/.test(product))throw Error(`Строка ${i+2}: некорректное название товара.`);if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!Number.isFinite(Date.parse(date))||new Date(date).toISOString().slice(0,10)!==date)throw Error(`Строка ${i+2}: неверная дата.`);const x={product,date};for(const k of ['sold','prepared','price','cost']){if(r[k]===undefined||String(r[k]).trim()===''||!Number.isFinite(Number(r[k]))||Number(r[k])<0||Number(r[k])>1e8)throw Error(`Строка ${i+2}: неверное число ${k}.`);x[k]=Number(r[k]);}if(!Number.isInteger(x.sold)||!Number.isInteger(x.prepared)||x.sold>x.prepared)throw Error(`Строка ${i+2}: проверьте целые объёмы продаж и приготовления.`);const key=JSON.stringify([date,product]);if(seen.has(key))throw Error(`Повтор даты и товара в строке ${i+2}.`);seen.add(key);if(!map.has(product))map.set(product,[]);map.get(product).push(x);return x;});if(map.size>100)throw Error('Максимум 100 товаров.');let end;for(const [name,list] of map){list.sort((a,b)=>a.date.localeCompare(b.date));if(list.length<35)throw Error(`${name}: нужно минимум 35 дней истории.`);for(let i=1;i<list.length;i++){if(Date.parse(list[i].date)-Date.parse(list[i-1].date)!==86400000)throw Error(`${name}: в истории есть пропуски дат.`);if(list[i].cost!==list[0].cost||list[i].price!==list[0].price)throw Error(`${name}: нужны постоянные цена и себестоимость.`);}if(end&&end!==list.at(-1).date)throw Error('История всех товаров должна заканчиваться одной датой.');end=list.at(-1).date;}return out;}

if(typeof module!=="undefined")module.exports={parseCSV,validate};
